import java.util.ArrayList;
import java.util.List;

public class ListInterleaverTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        ArrayList<Integer> a = new ArrayList<>(List.of(1, 3, 5));
        ArrayList<Integer> b = new ArrayList<>(List.of(2, 4, 6));
        ArrayList<Integer> merged = ListInterleaver.interleave(a, b);
        check("equal lengths", "[1, 2, 3, 4, 5, 6]",
                merged == null ? null : merged.toString());
        check("first list unchanged", "[1, 3, 5]", a.toString());
        check("second list unchanged", "[2, 4, 6]", b.toString());

        ArrayList<Integer> longA = ListInterleaver.interleave(
                new ArrayList<>(List.of(1, 3, 5, 7, 9)), new ArrayList<>(List.of(2, 4)));
        check("leftovers from a are appended", "[1, 2, 3, 4, 5, 7, 9]",
                longA == null ? null : longA.toString());

        ArrayList<Integer> longB = ListInterleaver.interleave(
                new ArrayList<>(List.of(1)), new ArrayList<>(List.of(7, 8, 9)));
        check("leftovers from b are appended", "[1, 7, 8, 9]",
                longB == null ? null : longB.toString());

        ArrayList<Integer> oneEmpty = ListInterleaver.interleave(
                new ArrayList<>(), new ArrayList<>(List.of(4, 5)));
        check("empty a gives just b", "[4, 5]",
                oneEmpty == null ? null : oneEmpty.toString());

        ArrayList<Integer> bothEmpty = ListInterleaver.interleave(
                new ArrayList<>(), new ArrayList<>());
        check("both empty gives empty", "[]",
                bothEmpty == null ? null : bothEmpty.toString());
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

