import java.util.ArrayList;

public class ListInterleaver {

    public static ArrayList<Integer> interleave(ArrayList<Integer> a, ArrayList<Integer> b) {
        ArrayList<Integer> result = new ArrayList<>();
        int longer = Math.max(a.size(), b.size());
        for (int i = 0; i < longer; i++) {
            if (i < a.size()) {
                result.add(a.get(i));
            }
            if (i < b.size()) {
                result.add(b.get(i));
            }
        }
        return result;
    }
}
